  // Added 2026-09-21 with their sites, and MISSED HERE, which is how
  // `portal-undefined` got into the archive — see the note above this map.
  bond: "bond",
  metricon: "metricon",
  scentre: "scg",
  smartrecruiters: "sr",
  careercentre: "cc",
  martianlogic: "ml",
  plscareers: "pls",
  xmlfeed: "xml",
